using namespace std;

int main() {
    string s;
    cin >> s;
    long long n = s.size();
    // Pair (i, j), i < j, is mirrored in min(i + 1, n - j) substrings; sum that weight over all pairs.
    long long allPairs = 0;
    for (long long j = 0; j < n; j++) {
        long long threshold = n - j, small = min(j, threshold);
        allPairs += small * (small + 1) / 2 + (j - small) * threshold;
    }
    // Subtract the weight of equal-letter pairs: per letter, i + 1 < n - j splits the earlier positions.
    vector<vector<long long>> positions(26);
    for (long long i = 0; i < n; i++) positions[s[i] - 'a'].push_back(i);
    long long equalPairs = 0;
    for (auto &places : positions) {
        vector<long long> prefix(1, 0);
        for (long long i : places) prefix.push_back(prefix.back() + i + 1);
        for (size_t k = 0; k < places.size(); k++) {
            long long j = places[k];
            long long split = lower_bound(places.begin(), places.begin() + k, n - j) - places.begin();
            equalPairs += prefix[split] + ((long long)k - split) * (n - j);
        }
    }
    cout << allPairs - equalPairs << '\n';
}

import java.io.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static String next() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = read();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        String s = next();
        int n = s.length();
        // Pair (i, j), i < j, is mirrored in min(i + 1, n - j) substrings; sum that weight over all pairs.
        long allPairs = 0;
        for (long j = 0; j < n; j++) {
            long threshold = n - j, small = Math.min(j, threshold);
            allPairs += small * (small + 1) / 2 + (j - small) * threshold;
        }
        // Subtract the weight of equal-letter pairs: per letter, i + 1 < n - j splits the earlier positions.
        int[] cnt = new int[26];
        for (int i = 0; i < n; i++) cnt[s.charAt(i) - 'a']++;
        int[][] positions = new int[26][];
        for (int c = 0; c < 26; c++) positions[c] = new int[cnt[c]];
        int[] fill = new int[26];
        for (int i = 0; i < n; i++) positions[s.charAt(i) - 'a'][fill[s.charAt(i) - 'a']++] = i;
        long equalPairs = 0;
        for (int[] places : positions) {
            long[] prefix = new long[places.length + 1];
            for (int k = 0; k < places.length; k++) prefix[k + 1] = prefix[k] + places[k] + 1;
            for (int k = 0; k < places.length; k++) {
                long j = places[k];
                // lower_bound of n - j within places[0..k)
                int lo = 0, hi = k;
                while (lo < hi) {
                    int mid = (lo + hi) >>> 1;
                    if (places[mid] < n - j) lo = mid + 1;
                    else hi = mid;
                }
                equalPairs += prefix[lo] + (long) (k - lo) * (n - j);
            }
        }
        System.out.println(allPairs - equalPairs);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
	"sort"
)

var data []byte
var pos int

func skip() {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
}

func nextToken() string {
	skip()
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return string(data[start:pos])
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	s := nextToken()
	n := int64(len(s))
	// Pair (i, j), i < j, is mirrored in min(i + 1, n - j) substrings; sum that weight over all pairs.
	var allPairs int64
	for j := int64(0); j < n; j++ {
		threshold := n - j
		small := min(j, threshold)
		allPairs += small*(small+1)/2 + (j-small)*threshold
	}
	// Subtract the weight of equal-letter pairs: per letter, i + 1 < n - j splits the earlier positions.
	var positions [26][]int64
	for i := int64(0); i < n; i++ {
		positions[s[i]-'a'] = append(positions[s[i]-'a'], i)
	}
	var equalPairs int64
	for _, places := range positions {
		prefix := make([]int64, len(places)+1)
		for k, i := range places {
			prefix[k+1] = prefix[k] + i + 1
		}
		for k, j := range places {
			split := sort.Search(k, func(t int) bool { return places[t] >= n-j })
			equalPairs += prefix[split] + int64(k-split)*(n-j)
		}
	}
	fmt.Println(allPairs - equalPairs)
}
